-- UniCloud portal, initial schema: the PostgreSQL copy of db/migration/V1__init_schema.sql.
-- Production runs MySQL and the files in db/migration. Staging (Render) runs PostgreSQL and the
-- files here, chosen with SPRING_FLYWAY_LOCATIONS=classpath:db/migration-postgresql.
-- Every MySQL migration needs a copy here with the same version and name, and the same tables,
-- columns, keys and checks. Never edit a copy after it has run: add a new version instead.
--
-- How the MySQL types map:
--   BIGINT/INT UNSIGNED AUTO_INCREMENT  -> BIGINT/INTEGER GENERATED BY DEFAULT AS IDENTITY
--   TINYINT UNSIGNED, SMALLINT UNSIGNED -> SMALLINT (the entities map these columns to Byte or Short)
--   DATETIME(3)                         -> TIMESTAMP(3) WITH TIME ZONE (the app writes UTC)
--   ON UPDATE CURRENT_TIMESTAMP(3)      -> the set_updated_at() trigger below
--   KEY name (cols)                     -> CREATE INDEX name ON table (cols)

-- Everyone who can log in.
CREATE TABLE users (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY,
    email          VARCHAR(254)    NOT NULL,
    password_hash  VARCHAR(255)    NOT NULL,   -- BCrypt or Argon2 hash, never the password itself
    first_name     VARCHAR(100)    NOT NULL,
    last_name      VARCHAR(100)    NOT NULL,
    role           VARCHAR(16)     NOT NULL,
    enabled        BOOLEAN         NOT NULL DEFAULT TRUE,
    created_at     TIMESTAMP(3) WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at     TIMESTAMP(3) WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    PRIMARY KEY (id),
    CONSTRAINT uq_users_email UNIQUE (email),
    CONSTRAINT chk_users_role CHECK (role IN ('STUDENT', 'TEACHER', 'INSPECTOR', 'ADMIN'))
);

-- Academic data, one row per student (one-to-one with users).
CREATE TABLE students (
    user_id         BIGINT           NOT NULL,
    faculty_number  VARCHAR(20)      NOT NULL,
    specialty       VARCHAR(200)     NOT NULL,
    study_year      SMALLINT         NOT NULL,
    status          VARCHAR(16)      NOT NULL DEFAULT 'ACTIVE',
    PRIMARY KEY (user_id),
    CONSTRAINT uq_students_faculty_number UNIQUE (faculty_number),
    CONSTRAINT fk_students_user FOREIGN KEY (user_id) REFERENCES users (id),
    CONSTRAINT chk_students_study_year CHECK (study_year BETWEEN 1 AND 6),
    CONSTRAINT chk_students_status CHECK (status IN ('ACTIVE', 'INTERRUPTED', 'GRADUATED'))
);

-- The catalogue: facts about a course that don't change between semesters.
CREATE TABLE courses (
    id            INTEGER GENERATED BY DEFAULT AS IDENTITY,
    code          VARCHAR(16)      NOT NULL,
    title         VARCHAR(200)     NOT NULL,
    ects_credits  SMALLINT         NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_courses_code UNIQUE (code),
    CONSTRAINT chk_courses_ects_credits CHECK (ects_credits BETWEEN 0 AND 255)   -- TINYINT UNSIGNED's range
);

-- A course running in one semester, with its teacher and seat limit.
CREATE TABLE course_offerings (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY,
    course_id    INTEGER           NOT NULL,
    semester     VARCHAR(16)       NOT NULL,   -- e.g. 2026-27-W
    teacher_id   BIGINT            NOT NULL,
    capacity     SMALLINT          NOT NULL,
    is_open      BOOLEAN           NOT NULL DEFAULT TRUE,
    PRIMARY KEY (id),
    CONSTRAINT uq_course_offerings_course_semester UNIQUE (course_id, semester),
    CONSTRAINT fk_course_offerings_course FOREIGN KEY (course_id) REFERENCES courses (id),
    CONSTRAINT fk_course_offerings_teacher FOREIGN KEY (teacher_id) REFERENCES users (id),
    CONSTRAINT chk_course_offerings_capacity CHECK (capacity > 0)
);
CREATE INDEX ix_course_offerings_semester ON course_offerings (semester);
CREATE INDEX ix_course_offerings_teacher ON course_offerings (teacher_id);

-- Who is enrolled in what. It references students, so only students can enroll.
CREATE TABLE enrollments (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY,
    student_id   BIGINT          NOT NULL,
    offering_id  BIGINT          NOT NULL,
    status       VARCHAR(16)     NOT NULL DEFAULT 'ENROLLED',
    created_at   TIMESTAMP(3) WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at   TIMESTAMP(3) WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    PRIMARY KEY (id),
    CONSTRAINT uq_enrollments_student_offering UNIQUE (student_id, offering_id),   -- stops double clicks
    CONSTRAINT fk_enrollments_student FOREIGN KEY (student_id) REFERENCES students (user_id),
    CONSTRAINT fk_enrollments_offering FOREIGN KEY (offering_id) REFERENCES course_offerings (id),
    CONSTRAINT chk_enrollments_status CHECK (status IN ('ENROLLED', 'CANCELLED'))
);
CREATE INDEX ix_enrollments_offering_status ON enrollments (offering_id, status);   -- counts taken seats fast

-- MySQL's ON UPDATE CURRENT_TIMESTAMP(3): when an update changes a row and doesn't set
-- updated_at itself, updated_at becomes the current time.
CREATE FUNCTION set_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.updated_at IS NOT DISTINCT FROM OLD.updated_at THEN
        NEW.updated_at := CURRENT_TIMESTAMP(3);
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_users_updated_at BEFORE UPDATE ON users
    FOR EACH ROW WHEN (OLD.* IS DISTINCT FROM NEW.*) EXECUTE FUNCTION set_updated_at();

CREATE TRIGGER trg_enrollments_updated_at BEFORE UPDATE ON enrollments
    FOR EACH ROW WHEN (OLD.* IS DISTINCT FROM NEW.*) EXECUTE FUNCTION set_updated_at();
